INSERT INTO profile_seed VALUES
  ('CASE-036', '2739a5c9-404f-50d7-bbe7-5cf17516cb98'::uuid, 'tama-art-university-hachioji-library', '艺术大学图书馆以拱形连续空间支持阅读、放松、研究和创作灵感。', NULL, 'Tama Art University Library is a reference case for reading library, Design topic: art大学, learning, creative production. It can inform thesis thinking about mixed programs, operation, and place-making.', 'アーチ状の構造が連続する大学図書館。静かな学習、創作前の調査、開放的な通り抜けが同居する空間を比較できる。', ARRAY['图书馆', '艺术大学', '学习', '创作', '开放空间']::text[], '{}'::text[], ARRAY['library', 'Design topic: art大学', 'learning', 'creative production', 'openspace']::text[], ARRAY['図書館', 'アート大学', '学習', '創作', '開放空間']::text[], NULL, NULL, 'https://www.tamabi.ac.jp/en/about/library/', 'published'),
  ('CASE-076', 'bed234bc-94f7-57d1-8592-3ea05e6bbbb5'::uuid, 'kozakai-kifukan-community-center', '社区中心、图书馆、儿童中心和市政分所复合，用共享中庭组织一站式公共服务。', NULL, 'Kozakai Kifukan Community Center is a reference case for reading communitycenter, library, childrencenter, Design topic: 市政service. It can inform thesis thinking about mixed programs, operation, and place-making.', 'コミュニティセンター、図書館、子ども支援、行政サービスをまとめた地域拠点。日常の用事を一つの公共施設に重ねる参考になる。', ARRAY['社区中心', '图书馆', '儿童中心', '市政服务', '复合公共建筑']::text[], '{}'::text[], ARRAY['communitycenter', 'library', 'childrencenter', 'Design topic: 市政service', 'Design topic: 复合public建筑']::text[], ARRAY['コミュニティセンター', '図書館', '子ども支援', '行政サービス', '地域拠点']::text[], NULL, NULL, 'https://www.c-and-a.co.jp/en/projects/kozakaikifukan/', 'published'),
  ('CASE-081', '1ed15436-687d-5020-a0ef-b1e28a0f19e1'::uuid, 'sukagawa-community-center-tette', '东日本大震灾后的市民交流中心复合图书馆、博物馆、育儿支援和咖啡，重建城市中心的公共生活。', NULL, 'Sukagawa Community Center tette is a reference case for reading Design topic: post-disaster复兴, communitycenter, library, childcaresupport. It can inform thesis thinking about mixed programs, operation, and place-making.', '「Sukagawa Community Center tette」は、災後復興・コミュニティセンター・図書館・子育て支援の関係を読み取る参考事例。用途の複合、運営、居場所のつくり方を卒業設計に転用して考えられる。', ARRAY['灾后复兴', '社区中心', '图书馆', '育儿支援', '市民交流']::text[], '{}'::text[], ARRAY['Design topic: post-disaster复兴', 'communitycenter', 'library', 'childcaresupport', 'citizenexchange']::text[], ARRAY['災後復興', 'コミュニティセンター', '図書館', '子育て支援', '市民交流']::text[], NULL, NULL, 'https://unemori-archi.com/?works=sukagawa-civic-center-tentative-name', 'published'),
  ('CASE-092', 'f64260d6-2859-5735-b053-c74bafa46aed'::uuid, 'ishikawa-prefectural-library', '大型公共图书馆通过环形书架、阶梯阅读和交流空间，把阅读设施转为开放文化客厅。', NULL, 'Ishikawa Prefectural Library is a reference case for reading library, cultureexchange, learning, Design topic: 无障碍. It can inform thesis thinking about mixed programs, operation, and place-making.', '大きな閲覧空間と多様な滞在場所を持つ県立図書館。調べる、相談する、休む、学ぶ行為を広く受け止める公共性を読める。', ARRAY['图书馆', '文化交流', '学习', '无障碍', '公共客厅']::text[], '{}'::text[], ARRAY['library', 'cultureexchange', 'learning', 'Design topic: 无障碍', 'public living room']::text[], ARRAY['図書館', '学習', '地域拠点', '滞在', '情報相談']::text[], NULL, NULL, 'https://www.library.pref.ishikawa.lg.jp/category/aboutlibrary/2983.html', 'published'),
  ('CASE-095', '6b926e74-2b36-53d4-a5e2-7dae96b56904'::uuid, 'nakajima-library-akita-international-university', '24小时大学图书馆以本之竞技场组织学习，提供全天候、安静且高度集中的知识空间。', NULL, 'Nakajima Library Akita International University is a reference case for reading nightlearning, Design topic: 大学library, Design topic: 24小时, Design topic: 木构. It can inform thesis thinking about mixed programs, operation, and place-making.', '大学図書館の静かな学習環境。集中、滞在、資料探索を支え、学校外の学びや制作前の調査空間として比較できる。', ARRAY['夜间学习', '大学图书馆', '24小时', '木构', '自习']::text[], '{}'::text[], ARRAY['nightlearning', 'Design topic: 大学library', 'Design topic: 24小时', 'Design topic: 木构', 'Design topic: 自习']::text[], ARRAY['図書館', '大学', '学習', '静かな滞在', '資料探索']::text[], NULL, NULL, 'https://web.aiu.ac.jp/en/education/support/library/outline/', 'published'),
  ('CASE-098', '5eb66d05-ac6b-5b59-8207-0be231f3706e'::uuid, 'helsinki-central-library-oodi', '中央图书馆把阅读、制作、活动和城市阳台复合，成为免费、安全、开放的市民客厅。', NULL, 'Helsinki Central Library Oodi is a reference case for reading library, Design topic: citizen客厅, makingspace, Design topic: urban阳台. It can inform thesis thinking about mixed programs, operation, and place-making.', '図書館を読書だけでなく、制作、学習、市民活動のプラットフォームとして開く事例。多様な利用者が滞在できる公共性を読める。', ARRAY['图书馆', '市民客厅', '制作空间', '城市阳台', '公共性']::text[], '{}'::text[], ARRAY['library', 'Design topic: citizen客厅', 'makingspace', 'Design topic: urban阳台', 'publicness']::text[], ARRAY['図書館', '市民活動', '学習', '制作', '開放性']::text[], NULL, NULL, 'https://oodihelsinki.fi/en/what-is-oodi/architecture/', 'published'),
  ('CASE-101', '06beedb1-fe15-5724-bc46-994a829e5ce1'::uuid, 'dokk1', '图书馆、市民服务、交通和港湾广场复合成城市客厅。', NULL, 'A hybrid civic library combining library, citizen service, transit, and harbor public space.', '図書館、市民サービス、交通、港の広場を重ねた大型公共リビング。駅前や水辺の学習拠点を考える参考になる。', ARRAY['图书馆', '市民服务', '港湾', '公共客厅', '交通']::text[], '{}'::text[], ARRAY['library', 'citizen service', 'harbor', 'public living room', 'transit']::text[], ARRAY['図書館', '市民サービス', '港', '公共リビング', '交通']::text[], NULL, NULL, 'https://www.shl.dk/en/work/dokk1-aarhus-central-library-and-culture-house/experience', 'published'),
  ('CASE-105', '6901a4d1-0a4a-5833-b59d-01d2bcf1cc75'::uuid, 'deichman-bjorvika', '海边图书馆把学习、制作、剧场和城市客厅叠合在一起。', NULL, 'A waterfront library combining learning, making, performance, cafe, and civic living room functions.', '水辺の図書館に、学習、制作、劇場、カフェ、都市のリビングを重ねた事例。駅前や港の公共施設を考える参考になる。', ARRAY['图书馆', '水边', '市民活动', '制作', '城市客厅']::text[], '{}'::text[], ARRAY['library', 'waterfront', 'civic activity', 'making', 'urban living room']::text[], ARRAY['図書館', '水辺', '市民活動', '制作', '都市リビング']::text[], NULL, NULL, 'https://www.lundhagem.no/work/deichman-library', 'published'),
  ('CASE-112', 'badd5949-61cf-5e7c-83c2-80415f8c7592'::uuid, 'peckham-library', '図書館を高く持ち上げ、街に開いた入口と学習空間をつくった事例。地域の知識拠点と象徴性を比較できる。', NULL, 'Reference case for Peckham Library: useful for comparing public program, urban interface, operation, and spatial experience.', '図書館を高く持ち上げ、街に開いた入口と学習空間をつくった事例。地域の知識拠点と象徴性を比較できる。', ARRAY['図書館', '地域学習', '公共入口', '都市象徴', '若者']::text[], '{}'::text[], ARRAY['図書館', '地域学習', '公共入口', '都市象徴', '若者']::text[], ARRAY['図書館', '地域学習', '公共入口', '都市象徴', '若者']::text[], NULL, NULL, 'https://www.southwark.gov.uk/culture-and-sport/libraries/find-library/peckham-library', 'published'),
  ('CASE-113', '01f36d99-7beb-5310-acba-623b775ca9ca'::uuid, 'bibliotheca-alexandrina', '巨大な図書館を都市、海、研究、文化記憶と結びつけた事例。知識施設を都市スケールで考える参考になる。', NULL, 'Reference case for Bibliotheca Alexandrina: useful for comparing public program, urban interface, operation, and spatial experience.', '巨大な図書館を都市、海、研究、文化記憶と結びつけた事例。知識施設を都市スケールで考える参考になる。', ARRAY['図書館', '文化記憶', '研究', '海辺', '公共性']::text[], '{}'::text[], ARRAY['図書館', '文化記憶', '研究', '海辺', '公共性']::text[], ARRAY['図書館', '文化記憶', '研究', '海辺', '公共性']::text[], NULL, NULL, 'https://www.snohetta.com/projects/bibliotheca-alexandrina', 'published'),
  ('CASE-114', 'e6b45af1-459e-56d2-b8a7-e4efa60a3776'::uuid, 'lochal-public-library', '旧鉄道工場を図書館、制作、イベント、学習の場に転用した事例。産業遺産と知識空間の接続を読める。', NULL, 'Reference case for LocHal Library: useful for comparing public program, urban interface, operation, and spatial experience.', '旧鉄道工場を図書館、制作、イベント、学習の場に転用した事例。産業遺産と知識空間の接続を読める。', ARRAY['図書館', '産業遺産', '再利用', '制作', '市民活動']::text[], '{}'::text[], ARRAY['図書館', '産業遺産', '再利用', '制作', '市民活動']::text[], ARRAY['図書館', '産業遺産', '再利用', '制作', '市民活動']::text[], NULL, NULL, 'https://www.civicarchitects.eu/projects/lochal-tilburg', 'published'),
  ('CASE-115', 'abd3201b-abdd-5acf-a52c-c9914f65698f'::uuid, 'idea-store-whitechapel', '図書館と生涯学習を商店街のような日常動線に重ねた事例。多文化地域の学習入口として比較できる。', NULL, 'Reference case for Idea Store Whitechapel: useful for comparing public program, urban interface, operation, and spatial experience.', '図書館と生涯学習を商店街のような日常動線に重ねた事例。多文化地域の学習入口として比較できる。', ARRAY['図書館', '生涯学習', '多文化', '商店街', '公共サービス']::text[], '{}'::text[], ARRAY['図書館', '生涯学習', '多文化', '商店街', '公共サービス']::text[], ARRAY['図書館', '生涯学習', '多文化', '商店街', '公共サービス']::text[], NULL, NULL, 'https://www.adjaye.com/work/idea-store-whitechapel/', 'published'),
  ('CASE-130', '7cdda9cd-7b2c-57b0-8b29-db78d2ff7248'::uuid, 'book-mountain-spijkenisse', '本棚を山のように積み上げ、図書館を地域の象徴的な学習風景にした事例。読書と空間体験を結べる。', NULL, 'Reference case for Book Mountain: useful for comparing public program, urban interface, operation, and spatial experience.', '本棚を山のように積み上げ、図書館を地域の象徴的な学習風景にした事例。読書と空間体験を結べる。', ARRAY['図書館', '本棚', '地域象徴', '読書', '学習風景']::text[], '{}'::text[], ARRAY['図書館', '本棚', '地域象徴', '読書', '学習風景']::text[], ARRAY['図書館', '本棚', '地域象徴', '読書', '学習風景']::text[], NULL, NULL, 'https://www.mvrdv.com/projects/126/book-', 'published'),
  ('CASE-137', '6f349aa6-a2bc-58f0-be15-347f1c8aae62'::uuid, 'library-of-birmingham', '大規模図書館を都市中心部の学習、展望、滞在の拠点にした事例。公共図書館の象徴性を読める。', NULL, 'Reference case for Library of Birmingham: useful for comparing public program, urban interface, operation, and spatial experience.', '大規模図書館を都市中心部の学習、展望、滞在の拠点にした事例。公共図書館の象徴性を読める。', ARRAY['図書館', '都心', '学習', '展望', '公共性']::text[], '{}'::text[], ARRAY['図書館', '都心', '学習', '展望', '公共性']::text[], ARRAY['図書館', '都心', '学習', '展望', '公共性']::text[], NULL, NULL, 'https://www.mecanoo.nl/Projects/project/57/Library-of-Birmingham?t=0', 'published');
